mapper.update:
update ${database.prefix.activity}hou_addon_activity_voucher_common
set voucher_state = #{voucherState}

    , voucher_order_id = #{orderId}

where voucher_id
=#{voucherId}

mapper.select:
select count(voucher_id)
from ${database.prefix.activity}hou_addon_activity_voucher_base
where voucher_t_id = #{param.voucherTId}
  and voucher_owner_id = #{param.voucherOwnerId}

SELECT voucher_id, yvb.voucher_t_id, voucher_title, voucher_start_date, voucher_end_date, voucher_price, gc.common_image, voucher_limit, voucher_shop_id, voucher_state, voucher_active_date, voucher_owner_id, voucher_owner_name, voucher_order_id, gmsb.shop_name, avt.is_shop_voucher FROM ${database.prefix.activity}hou_addon_activity_voucher_base yvb LEFT JOIN ${database.prefix.business}hou_shop_base gmsb ON gmsb.supplier_shop_id = yvb.voucher_shop_id LEFT JOIN ${database.prefix.activity}hou_addon_activity_voucher_common gpvc ON gpvc.voucher_t_id = yvb.voucher_t_id LEFT JOIN ${database.prefix.activity}hou_addon_activity_voucher_template avt ON avt.voucher_t_id = yvb.voucher_t_id LEFT JOIN ${database.prefix.goods}hou_goods_common gc ON gc.common_id = gpvc.common_id WHERE yvb.voucher_owner_id = #{param.voucherOwnerId} and yvb.voucher_state = #{param.voucherState} AND avt.is_shop_voucher = 1
and ((gpvc.common_id in (
#{commonId}
) ) or (gpvc.common_id is null) )
and yvb.voucher_limit <= #{param.order}
and yvb.voucher_shop_id = #{param.voucherShopId}
and yvb.voucher_start_date <= now()
GROUP BY yvb.voucher_id ORDER BY yvb.voucher_price

select count(voucher_id)
from ${database.prefix.activity}hou_addon_activity_voucher_base
where voucher_t_id = #{param.voucherTId}
  and voucher_owner_id = #{param.voucherOwnerId}

SELECT vb.voucher_id, vb.voucher_t_id, vb.voucher_title, vb.voucher_start_date, vb.voucher_end_date, vb.voucher_price, vb.voucher_limit, vb.voucher_shop_id, vb.voucher_state, vb.voucher_active_date, vb.voucher_owner_id, vb.voucher_owner_name, vb.voucher_order_id, avt.is_shop_voucher, gc.goods_id, vg.common_id, sb.shop_name FROM ${database.prefix.activity}hou_addon_activity_voucher_base vb LEFT JOIN ${database.prefix.business}hou_shop_base sb ON sb.supplier_shop_id = vb.voucher_shop_id LEFT JOIN ${database.prefix.activity}hou_addon_activity_voucher_template avt ON avt.voucher_t_id = vb.voucher_t_id LEFT JOIN ${database.prefix.activity}hou_addon_activity_voucher_goods vg ON vg.voucher_t_id = vb.voucher_t_id LEFT JOIN ${database.prefix.goods}hou_goods_common gc ON gc.common_id = vg.common_id WHERE 1=1
and vb.voucher_owner_id = #{param.voucherOwnerId}
and vb.voucher_state = #{param.voucherState}
GROUP BY vb.voucher_id ORDER BY vb.voucher_price desc

SELECT voucher_id, yvb.voucher_t_id, voucher_title, voucher_start_date, voucher_end_date, voucher_price, gc.common_image, voucher_limit, voucher_shop_id, voucher_state, voucher_active_date, voucher_owner_id, voucher_owner_name, voucher_order_id, gmsb.shop_name, avt.is_shop_voucher FROM ${database.prefix.activity}hou_addon_activity_voucher_base yvb LEFT JOIN ${database.prefix.business}hou_shop_base gmsb ON gmsb.supplier_shop_id = yvb.voucher_shop_id LEFT JOIN ${database.prefix.activity}hou_addon_activity_voucher_common gpvc ON gpvc.voucher_t_id = yvb.voucher_t_id LEFT JOIN ${database.prefix.activity}hou_addon_activity_voucher_template avt ON avt.voucher_t_id = yvb.voucher_t_id LEFT JOIN ${database.prefix.goods}hou_goods_common gc ON gc.common_id = gpvc.common_id WHERE yvb.voucher_owner_id = #{userId} and yvb.voucher_state = 1 and avt.is_shop_voucher = 2 and gpvc.common_id = #{commonId} and yvb.voucher_limit <= #{goodOrderPrice} and yvb.voucher_shop_id = #{shopId} and yvb.voucher_start_date <= now()
and yvb.voucher_id not in (
#{voucherId}
)
GROUP BY yvb.voucher_id,gpvc.common_id ORDER BY yvb.voucher_price
